package fr.cercle.decoupe;
import android.app.Activity;import android.os.Bundle;import android.view.*;import android.graphics.*;import android.content.*;import java.util.*;
public class MainActivity extends Activity{Game game;public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);game=new Game(this);setContentView(game);}public void onPause(){super.onPause();game.paused=true;}public void onResume(){super.onResume();if(game!=null)game.last=0;}
class Game extends View{Engine e=new Engine(1,System.nanoTime());Paint p=new Paint(3);float scale=1,ox,oy,sx,sy,ex,ey;boolean paused=false,drag=false;long last;int best;final int bg=Color.rgb(13,23,29),panel=Color.rgb(25,42,49),fg=Color.rgb(237,232,215),muted=Color.rgb(155,178,181),accent=Color.rgb(231,180,105);
Game(Context c){super(c);best=getPreferences(0).getInt("best",0);setContentDescription("Découpe, jeu hors ligne");}void text(Canvas c,String s,float x,float y,int size,int col){p.setColor(col);p.setStyle(Paint.Style.FILL);p.setTypeface(Typeface.create("sans-serif",0));p.setTextSize(size);c.drawText(s,x,y,p);}void box(Canvas c,float x,float y,float w,float h,int col){p.setColor(col);p.setStyle(Paint.Style.FILL);c.drawRoundRect(x,y,x+w,y+h,15,15,p);}void line(Canvas c,float x,float y,float a,float b,int col,int width){p.setColor(col);p.setStrokeWidth(width);c.drawLine(x,y,a,b,p);}void circle(Canvas c,float x,float y,float r,int col){p.setColor(col);p.setStyle(Paint.Style.FILL);c.drawCircle(x,y,r,p);}void button(Canvas c,String s,float x,float y,float w,int col){box(c,x,y,w,88,col);text(c,s,x+16,y+53,23,col==accent?bg:fg);}void poly(Canvas c,List<float[]> a,int col){if(a.isEmpty())return;Path path=new Path();path.moveTo(a.get(0)[0],a.get(0)[1]);for(int i=1;i<a.size();i++)path.lineTo(a.get(i)[0],a.get(i)[1]);path.close();p.setColor(col);p.setStyle(Paint.Style.FILL);c.drawPath(path,p);}void wrap(Canvas c,String s,float y){String line="";int row=0;p.setTextSize(22);for(String w:s.split(" ")){if(p.measureText(line+w)>620){text(c,line,45,y+row*30,22,fg);line="";row++;}line+=w+" ";}text(c,line,45,y+row*30,22,fg);}
protected void onDraw(Canvas c){long now=System.nanoTime();float dt=last==0?0:Math.min(.04f,(now-last)/1e9f);last=now;if(!paused)e.tick(dt);if(e.over&&e.score>best){best=e.score;getPreferences(0).edit().putInt("best",best).apply();}scale=Math.min(getWidth()/720f,getHeight()/1280f);ox=(getWidth()-720*scale)/2;oy=(getHeight()-1280*scale)/2;c.drawColor(bg);c.save();c.translate(ox,oy);c.scale(scale,scale);text(c,"PARTIES COURTES / PROTOTYPE 0.1",30,45,17,muted);text(c,"Découpe",30,110,49,fg);button(c,"PAUSE",515,135,175,panel);text(c,"SCORE "+e.score+"  ·  RECORD "+best,30,190,22,accent);box(c,30,245,660,815,panel);
if(e.mode==0){text(c,"SALLE "+Math.min(6,e.round+1)+" / 6",50,285,24,accent);text(c,"VIE "+e.hp+" / "+e.maxHp+"   ÉNERGIE "+e.energy+" / 3",50,330,24,fg);box(c,50,355,610*e.hp/(float)e.maxHp,12,accent);if(e.upgrade){text(c,"CHOISIS UNE AMÉLIORATION",50,430,25,fg);for(int i=0;i<3;i++)button(c,e.offerName(e.offers[i]),55,485+i*125,610,accent);wrap(c,"Une seule offre. Les améliorations se combinent jusqu’à la sixième porte.",925);}else{circle(c,360,535,e.round==5?95:70,Color.rgb(153,94,85));text(c,e.round==5?"GARDIEN":"VEILLEUR",260,545,26,fg);text(c,"ADVERSAIRE : "+Math.max(0,e.enemy)+" / "+e.enemyMax+" PV",155,690,27,fg);wrap(c,e.intentName(),765);text(c,"FRAPPE "+e.power+" · ARMURE "+e.armor,50,890,23,accent);text(c,"POISON "+e.poison+" · RIPOSTE "+e.counter,50,930,22,muted);text(c,"Parer réduit le coup de 9. Esquiver coûte 1 énergie.",50,1000,20,muted);}}
if(e.mode==1){text(c,"PLAQUE "+Math.min(3,e.round+1)+" / 3 · "+e.cuts+" / 2 TRAITS",50,285,23,muted);text(c,"GARDE "+e.target+" %",50,345,35,accent);if(e.stage==1){poly(c,e.partA,accent);poly(c,e.partB,Color.rgb(117,145,170));}else poly(c,e.polygon,accent);if(drag)line(c,sx,sy,ex,ey,fg,4);text(c,"CONSERVÉ : "+Math.round(e.percent())+" %",50,1015,25,fg);}
if(e.mode==2){text(c,"PASSAGE "+Math.min(3,e.round+1)+" / 3",50,285,24,accent);text(c,"PORTE CLAIRE = OUVERTE",50,330,21,fg);box(c,300,365,120,38,accent);text(c,"SORTIE",310,392,20,bg);for(int i=0;i<3;i++){float gy=500+i*155;int col=e.open(i)?accent:Color.rgb(156,87,79);box(c,65,gy-8,e.gaps[i]-120,16,muted);box(c,e.gaps[i]+55,gy-8,600-e.gaps[i]-55,16,muted);if(!e.open(i))box(c,e.gaps[i]-55,gy-8,110,16,col);float phase=(e.time+i*.7f)%3.6f;box(c,e.gaps[i]-55,gy+22,110*(phase/3.6f),5,col);text(c,e.open(i)?"OUVERTE":"ATTENDS",e.gaps[i]-50,gy-30,16,col);if(!e.gems[i])circle(c,i%2==0?590:125,560+i*140,11,Color.rgb(231,180,105));}circle(c,e.x,e.y,15,fg);}
wrap(c,e.message,1102);if(e.mode==0&&!e.upgrade){button(c,"FRAPPER",30,1180,210,accent);button(c,"PARER",255,1180,210,panel);button(c,e.energy>0?"ESQUIVER":"ÉPUISÉ",480,1180,210,panel);}if(e.mode==1){button(c,"REFAIRE",30,1180,310,panel);button(c,"VALIDER",360,1180,330,accent);}if(e.mode==2)text(c,"Glisse le disque. Les détours dorés rapportent +30.",35,1230,22,muted);
if(e.over){box(c,55,430,610,420,bg);text(c,e.mode==0?(e.won?"SIX PORTES FRANCHIES":"FIN DE TENTATIVE"):"PARTIE TERMINÉE",85,510,31,accent);text(c,e.score+" points",85,600,50,fg);text(c,"RECORD "+best,85,660,25,muted);button(c,"REJOUER",85,720,550,accent);}if(paused){box(c,55,430,610,350,bg);text(c,"PAUSE",95,520,40,fg);text(c,"Touche pour reprendre.",95,590,27,muted);button(c,"REPRENDRE",95,650,530,accent);}c.restore();if(!paused&&!e.over)postInvalidateDelayed(16);}
public boolean onTouchEvent(MotionEvent ev){float x=(ev.getX()-ox)/scale,y=(ev.getY()-oy)/scale;int a=ev.getActionMasked();if(a==MotionEvent.ACTION_CANCEL){drag=false;e.moving=false;return true;}if(a==0){if(paused){paused=false;last=0;invalidate();return true;}if(e.over){if(y>710&&y<825){e=new Engine(1,System.nanoTime());invalidate();}return true;}if(x>500&&y>130&&y<230){paused=true;e.moving=false;drag=false;invalidate();return true;}if(e.mode==0){if(e.upgrade){for(int i=0;i<3;i++)if(y>485+i*125&&y<573+i*125)e.choose(i);}else if(y>1180)e.act(x<240?0:x<475?1:2);}if(e.mode==1){if(y>1180){if(x<350)e.plate();else e.validate();}else if(e.stage==1)e.keep(x,y);else if(y>350&&y<1035){drag=true;sx=ex=x;sy=ey=y;}}if(e.mode==2&&y>350&&y<1030){e.tx=x;e.ty=y;e.moving=true;}invalidate();return true;}if(a==2){if(e.mode==1&&drag){ex=x;ey=y;}if(e.mode==2&&e.moving){e.tx=x;e.ty=y;}invalidate();}if(a==1){if(e.mode==1&&drag){drag=false;e.cut(sx,sy,x,y);}if(e.mode==2)e.moving=false;invalidate();}return true;}
}}
